corrected_code:
const Redis = require('ioredis');
const redis = new Redis(process.env.REDIS_URL);
const { db } = require('../db');

async function consumeOrgRoleUpdates() {
  while (true) {
    const streams = await redis.xreadgroup('GROUP', 'role-sync', 'worker-1', 'BLOCK', 2000, 'STREAMS', 'stream:org:role-updates', '>');
    if (!streams) continue;

    for (const [, messages] of streams) {
      for (const [id, fields] of messages) {
        const { organizationId, memberId, newRole, actorId } = JSON.parse(fields[1]);

        const actor = await db.query(
          'SELECT role FROM organization_members WHERE organization_id = $1 AND user_id = $2',
          [organizationId, actorId]
        );
        if (actor.rows[0]?.role !== 'OWNER') {
          console.error(`Rejected unauthorized role update on org ${organizationId} by actor ${actorId}`);
          await redis.xack('stream:org:role-updates', 'role-sync', id);
          continue;
        }

        await db.query(
          'UPDATE organization_members SET role = $1 WHERE organization_id = $2 AND user_id = $3',
          [newRole, organizationId, memberId]
        );
        await redis.xack('stream:org:role-updates', 'role-sync', id);
      }
    }
  }
}
